{
  "headline": "FDA's records trace our supply to a plant classified OAI 214 days before the shortage posting",
  "headline_cites": ["D10"],
  "sentences": [
    {
      "text": "FDA first posted the furosemide injection shortage on 2020-04-07 and it remains current as of 2026-10-21.",
      "cites": ["E69", "D19"]
    },
    {
      "text": "The Accord Healthcare label for furosemide names Intas Pharmaceuticals Limited as the manufacturing plant.",
      "cites": ["E18"]
    },
    {
      "text": "FDA inspection 1106244 at Pfizer Healthcare India Private Limited ended 2019-09-06 and was classified OAI, 214 days before the shortage posting.",
      "cites": ["D10"]
    },
    {
      "text": "FDA inspection 1191818 at Intas Pharmaceuticals Limited ended 2022-12-02 and was classified OAI, with the classification letter dated 2023-04-05.",
      "cites": ["E14", "D14"]
    },
    {
      "text": "An import alert 66-40 was issued for Intas Pharmaceuticals Limited on 2023-06-01 and again on 2023-11-14.",
      "cites": ["E16", "E17"]
    },
    {
      "text": "Warning letters were issued to Intas Pharmaceuticals Limited on 2023-07-28 and 2023-11-21.",
      "cites": ["E15", "E27"]
    },
    {
      "text": "The best option by rule is to buy from Amneal Pharmaceuticals LLC, which is not on FDA's shortage list today.",
      "cites": ["D16"]
    }
  ]
}
